command:
NODE2_IP=$(printf '%s\n' "$CLUSTER_HOSTS" | awk '$2=="node2" {print $1}'); [ -n "$NODE2_IP" ] || { printf '%s\n' 'node2 address not found' >&2; exit 1; }; sudo sh -c 'cat > /etc/named.conf' <<EOF
options {
    listen-on port 53 { 127.0.0.1; $NODE_IP; };
    listen-on-v6 { none; };
    directory "/var/named";
    recursion yes;
    allow-query { 127.0.0.1; 10.100.160.0/24; };
    forwarders { 10.100.160.1; };
    forward only;
    dnssec-validation yes;
};
zone "internal" IN {
    type master;
    file "internal.zone";
    allow-update { none; };
};
EOF
sudo sh -c 'cat > /var/named/internal.zone' <<EOF
\$TTL 300
@ IN SOA ns.internal. hostmaster.internal. (
    2026100301 3600 900 604800 300 )
  IN NS ns.internal.
ns IN A $NODE_IP
inventory-api IN A $NODE2_IP
EOF
sudo chown root:named /etc/named.conf /var/named/internal.zone; sudo chmod 640 /etc/named.conf /var/named/internal.zone; sudo restorecon -v /etc/named.conf /var/named/internal.zone; sudo named-checkconf /etc/named.conf; sudo named-checkzone internal /var/named/internal.zone

